import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { CommonModule } from '@angular/common';
import { NotesService, Note } from '../../services/notes.service';
import { NoteEditorComponent } from '../note-editor/note-editor.component';
import { ConfirmDialogComponent } from '../shared/confirm-dialog/confirm-dialog.component';

@Component({
  selector: 'app-note-detail',
  standalone: true,
  imports: [CommonModule, RouterLink, NoteEditorComponent, ConfirmDialogComponent],
  templateUrl: './note-detail.component.html',
  styleUrls: ['./note-detail.component.scss']
})
export class NoteDetailComponent implements OnInit {
  note?: Note;
  confirmOpen = false;

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private notesService: NotesService
  ) {}

  ngOnInit(): void {
    const id = this.route.snapshot.paramMap.get('id')!;
    this.notesService.getNote(id).subscribe(n => this.note = n);
  }

  onSaved(n: Note) {
    this.note = n;
  }

  requestDelete() {
    this.confirmOpen = true;
  }

  onConfirmDelete(confirmed: boolean) {
    this.confirmOpen = false;
    if (confirmed && this.note) {
      this.notesService.deleteNote(this.note.id).subscribe(() => {
        this.router.navigate(['/']);
      });
    }
  }
}
<section class="card">
  <div *ngIf="note; else missing">
    <div class="topbar">
      <a routerLink="/" class="btn btn-secondary" aria-label="Back to list">← Back</a>
      <button class="btn btn-danger" (click)="requestDelete()" aria-label="Delete note">Delete</button>
    </div>
    <app-note-editor [note]="note" (saved)="onSaved($event)"></app-note-editor>
  </div>
  <ng-template #missing>
    <p class="empty">Note not found.</p>
    <a routerLink="/" class="btn btn-secondary">Go back</a>
  </ng-template>

  <app-confirm-dialog
    [open]="confirmOpen"
    title="Delete this note?"
    message="This action cannot be undone."
    (closed)="onConfirmDelete($event)"
  ></app-confirm-dialog>
</section>
